#define R0K(T,M,name) extern "C" __global__ void __launch_bounds__(T) name(const float* q, const float* k, const float* cs, const float* sn, float* qo, float* ko, unsigned Rq, unsigned R, unsigned S) { r0body<T,M>(q,k,cs,sn,qo,ko,Rq,R,S); }
R0K(64,0,r0_64) R0K(256,0,r0_256) R0K(64,1,nt_64) R0K(256,1,nt_256) R0K(64,3,pl_64) R0K(256,3,pl_256)
// C: table in registers, loop over HG heads of one s per thread
template <int HG, bool PF>
__device__ __forceinline__ void cbody(const float* q, const float* k, const float* cs, const float* sn,
     float* qo, float* ko, unsigned BHq, unsigned BHk, unsigned S, unsigned nS, unsigned nTq) {
