    if (b < nTq) { x = q; y = qo; BH = BHq; t = b; } else { x = k; y = ko; BH = BHk; t = b - nTq; }
    const unsigned ht = t / nS, st = t - ht * nS;
    const unsigned j = threadIdx.x & 7;
    const unsigned s = st * 32 + (threadIdx.x >> 3);
    if (s >= S) return;
    const unsigned bh0 = ht * HG;
    const unsigned nh = min((unsigned)HG, BH - bh0);
    float cl[8], ch[8], sl[8], sh[8], xl[8], xh[8], ol[8], oh[8];
    const size_t stride = (size_t)S * 128;
    const float* xp = x + ((size_t)bh0 * S + s) * 128 + j * 8;
    float* yp = y + ((size_t)bh0 * S + s) * 128 + j * 8;
    LDX8(xp, xl); LDX8(xp + 64, xh);
    const float* cp = cs + (size_t)s * 128 + j * 8; const float* sp = sn + (size_t)s * 128 + j * 8;
    LD8(cp, cl); LD8(cp + 64, ch); LD8(sp, sl); LD8(sp + 64, sh);
    unsigned long long pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll 1
    for (unsigned h = 0; h < nh; ++h) {
        float nl[8], nhh[8];
        if (PF && h + 1 < nh) { LDX8(xp + stride, nl); LDX8(xp + stride + 64, nhh); }
#pragma unroll
        for (int e = 0; e < 8; ++e) { ol[e] = xl[e] * cl[e] - xh[e] * sl[e]; oh[e] = xh[e] * ch[e] + xl[e] * sh[e]; }
        ST8EL(yp, ol, pol); ST8EL(yp + 64, oh, pol);
        xp += stride; yp += stride;
        if (PF) { for (int e=0;e<8;++e){ xl[e]=nl[e]; xh[e]=nhh[e]; } }
        else if (h + 1 < nh) { LDX8(xp, xl); LDX8(xp + 64, xh); }
    }
