CK(2,true,C2p) CK(4,true,C4p) CK(4,false,C4n) CK(8,false,C8n)
'''
CS = {"C2p":2,"C4p":4,"C4n":4,"C8n":8}
names = ["r0_64","r0_256","nt_64","nt_256","pl_64","pl_256"] + list(CS)
K = {n: bp.cuda_kernel(SRC, n) for n in names}
for line in bp.resources(SRC).splitlines():
    if 'REG' in line: print(line.strip()[:40], end=' | ')
print()
K["nt_256"].set_smem(60000); K["nt_64"].set_smem(12000)
def make_fn(name):
    if name in CS:
        HG = CS[name]; kern = K[name]
        def fn(q,k,c,s_,qo,ko):
            B,H,S,_ = q.shape; Hk = k.shape[1]
            nS = (S+31)//32; nTq = ((B*H+HG-1)//HG)*nS; nTk = ((B*Hk+HG-1)//HG)*nS
            kern((nTq+nTk,), (256,), q,k,c,s_,qo,ko, B*H, B*Hk, S, nS, nTq)
        return fn
    pre, sm = (name[:-3], True) if name.endswith("occ") else (name, False)
    def fn(q,k,c,s_,qo,ko):
        S = q.shape[2]; Rq = q.numel()//128; R = Rq + k.numel()//128
        if R <= 262144: K[pre+"_64"](((R+7)//8,), (64,), q,k,c,s_,qo,ko,Rq,R,S, smem=11776 if sm else 0)
        else: K[pre+"_256"](((R+31)//32,), (256,), q,k,c,s_,qo,ko,Rq,R,S, smem=50*1024 if sm else 0)
    return fn
def mk(B,H,Hk,S):
    q = torch.randn(B,H,S,128,device='cuda'); k = torch.randn(B,Hk,S,128,device='cuda')
    c = torch.cos(torch.randn(S,128,device='cuda')); s = torch.sin(torch.randn(S,128,device='cuda'))
    return q,k,c,s
def ref(q,k,c,s):
    rh = lambda x: torch.cat((-x[...,64:], x[...,:64]),-1)
    return q*c+rh(q)*s, k*c+rh(k)*s
for shp in [(1,40,8,131),(2,48,6,919)]:
    q,k,c,s = mk(*shp); rq,rk = ref(q,k,c,s)
    for n in list(CS)+["pl"]:
        qo=torch.zeros_like(q); ko=torch.zeros_like(k); make_fn(n)(q,k,c,s,qo,ko); torch.cuda.synchronize()
        e = max((qo-rq).abs().max().item(), (ko-rk).abs().max().item())
        if e > 1e-5: print("BAD", n, shp, e)
