V = ["r0","nt","ntocc","pl"] + list(CS)
for mb, shp in SH.items():
    q,k,c,s = mk(*shp); qo=torch.empty_like(q); ko=torch.empty_like(k); out={}
    for rep in range(3):
        for v in V:
            out.setdefault(v,[]).append(bp.harness_time(make_fn(v), (q,k,c,s), (qo,ko), warmup=5, rep=20))
    b = sorted(out['r0'])[1]
    print(mb, f"r0:{b:.2f}", "  ".join(f"{v}:{sorted(out[v])[1]/b-1:+.1%}" for v in V[1:]), f"[{time.time()-t0:.0f}s]", flush=True)
    del q,k,qo,ko; torch.cuda.empty_cache()

