// tile kernel, heads fastest in CTA; S0: table row forced to s&1 (pattern cost only)
template <int TS, int HG, bool S0>
__device__ __forceinline__ void tilebody(const float* q, const float* k, const float* cs, const float* sn,
     float* qo, float* ko, unsigned BHq, unsigned BHk, unsigned S, unsigned nS, unsigned nTq) {
