    const size_t row = (size_t)bh * S + s;
    float xl[8], xh[8], cl[8], ch[8], sl[8], sh[8], ol[8], oh[8];
    LDX8(x + row*128 + j*8, xl); LDX8(x + row*128 + j*8 + 64, xh);
    const unsigned ts = S0 ? (s & 1) : s;
    const float* cp = cs + (size_t)ts * 128 + j * 8; const float* sp = sn + (size_t)ts * 128 + j * 8;
    LD8(cp, cl); LD8(cp + 64, ch); LD8(sp, sl); LD8(sp + 64, sh);
    unsigned long long pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll
    for (int e = 0; e < 8; ++e) { ol[e] = xl[e] * cl[e] - xh[e] * sl[e]; oh[e] = xh[e] * ch[e] + xl[e] * sh[e]; }
    y += row * 128 + j * 8;
    ST8EL(y, ol, pol); ST8EL(y + 64, oh, pol);
}
