// C2: 2 heads per thread fully unrolled, table loaded once; T threads -> T/8 s positions
template <bool PF>
__device__ __forceinline__ void c2body(const float* q, const float* k, const float* cs, const float* sn,
     float* qo, float* ko, unsigned BHq, unsigned BHk, unsigned S, unsigned nS, unsigned nTq, unsigned TSn) {
    unsigned b = blockIdx.x; const float* x; float* y; unsigned BH, t;
    if (b < nTq) { x = q; y = qo; BH = BHq; t = b; } else { x = k; y = ko; BH = BHk; t = b - nTq; }
    const unsigned ht = t / nS, st = t - ht * nS;
    const unsigned j = threadIdx.x & 7;
    const unsigned s = st * TSn + (threadIdx.x >> 3);
    if (s >= S) return;
    const unsigned bh0 = ht * 2;
    const bool two = bh0 + 1 < BH;
    const size_t stride = (size_t)S * 128;
    const float* xp = x + ((size_t)bh0 * S + s) * 128 + j * 8;
    float* yp = y + ((size_t)bh0 * S + s) * 128 + j * 8;
    float cl[8], ch[8], sl[8], sh[8], al[8], ah[8], bl[8], bhh[8], ol[8], oh[8];
