    unsigned b = blockIdx.x; const float* x; float* y; unsigned BH, t;
    if (b < nTq) { x = q; y = qo; BH = BHq; t = b; } else { x = k; y = ko; BH = BHk; t = b - nTq; }
    const unsigned ht = t / nS, st = t - ht * nS;
    const unsigned j = threadIdx.x & 7;
    const unsigned s = st * TSn + (threadIdx.x >> 3);
    if (s >= S) return;
    const unsigned bh0 = ht * 2;
    const bool two = bh0 + 1 < BH;
    const size_t stride = (size_t)S * 128;
    const float* xp = x + ((size_t)bh0 * S + s) * 128 + j * 8;
    float* yp = y + ((size_t)bh0 * S + s) * 128 + j * 8;
    float cl[8], ch[8], sl[8], sh[8], al[8], ah[8], bl[8], bhh[8], ol[8], oh[8];
    LDX8(xp, al); LDX8(xp + 64, ah);
    if (two) { LDX8(xp + stride, bl); LDX8(xp + stride + 64, bhh); }
    const float* cp = cs + (size_t)s * 128 + j * 8; const float* sp = sn + (size_t)s * 128 + j * 8;
    LD8(cp, cl); LD8(cp + 64, ch); LD8(sp, sl); LD8(sp + 64, sh);
    unsigned long long pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll
    for (int e = 0; e < 8; ++e) { ol[e] = al[e] * cl[e] - ah[e] * sl[e]; oh[e] = ah[e] * ch[e] + al[e] * sh[e]; }
    ST8EL(yp, ol, pol); ST8EL(yp + 64, oh, pol);
    if (two) {
#pragma unroll
      for (int e = 0; e < 8; ++e) { ol[e] = bl[e] * cl[e] - bhh[e] * sl[e]; oh[e] = bhh[e] * ch[e] + bl[e] * sh[e]; }
      ST8EL(yp + stride, ol, pol); ST8EL(yp + stride + 64, oh, pol);
    }
}
extern "C" __global__ void __launch_bounds__(64) C2_64(const float* q, const float* k, const float* cs, const float* sn, float* qo, float* ko, unsigned BHq, unsigned BHk, unsigned S, unsigned nS, unsigned nTq) { c2body<false>(q,k,cs,sn,qo,ko,BHq,BHk,S,nS,nTq,8); }
extern "C" __global__ void __launch_bounds__(128) C2_128(const float* q, const float* k, const float* cs, const float* sn, float* qo, float* ko, unsigned BHq, unsigned BHk, unsigned S, unsigned nS, unsigned nTq) { c2body<false>(q,k,cs,sn,qo,ko,BHq,BHk,S,nS,nTq,16); }
'''
TILES = {"W_2_4":(2,4),"W0_2_4":(2,4),"W_8_4":(8,4),"W0_8_4":(8,4)}
CC = {"C2_64":(64,8),"C2_128":(128,16)}
names = ["r0_64","r0_256","s0_64","s0_256"] + list(TILES) + list(CC)
K = {n: bp.cuda_kernel(SRC, n) for n in names}
for line in bp.resources(SRC).splitlines():
    if 'REG' in line or 'Function' in line: print(line.strip()[:28], end=' | ')
print()
def make_fn(name):
    if name in TILES:
        TS, HG = TILES[name]; kern = K[name]
        def fn(q,k,c,s_,qo,ko):
            B,H,S,_ = q.shape; Hk = k.shape[1]
            nS = (S+TS-1)//TS; nTq = ((B*H+HG-1)//HG)*nS; nTk = ((B*Hk+HG-1)//HG)*nS
            kern((nTq+nTk,), (TS*HG*8,), q,k,c,s_,qo,ko, B*H, B*Hk, S, nS, nTq)
        return fn
    if name in CC:
        T, TS = CC[name]; kern = K[name]
        def fn(q,k,c,s_,qo,ko):
            B,H,S,_ = q.shape; Hk = k.shape[1]
            nS = (S+TS-1)//TS; nTq = ((B*H+1)//2)*nS; nTk = ((B*Hk+1)//2)*nS
            kern((nTq+nTk,), (T,), q,k,c,s_,qo,ko, B*H, B*Hk, S, nS, nTq)
        return fn
    def fn(q,k,c,s_,qo,ko):
        S = q.shape[2]; Rq = q.numel()//128; R = Rq + k.numel()//128
        if name.endswith("_64"): K[name](((R+7)//8,), (64,), q,k,c,s_,qo,ko,Rq,R,S)
        else: K[name](((R+31)//32,), (256,), q,k,c,s_,qo,ko,Rq,R,S)
    return fn
def mk(B,H,Hk,S):
    q = torch.randn(B,H,S,128,device='cuda'); k = torch.randn(B,Hk,S,128,device='cuda')
    c = torch.cos(torch.randn(S,128,device='cuda')); s = torch.sin(torch.randn(S,128,device='cuda'))
    return q,k,c,s
def ref(q,k,c,s):
    rh = lambda x: torch.cat((-x[...,64:], x[...,:64]),-1)
    return q*c+rh(q)*s, k*c+rh(k)*s
for shp in [(1,40,8,131),(2,48,6,919)]:
